import{_ as n,h as r,i as e,c as l,v as o,p as d,x as t,m as h,e as s,S as c}from"./chunks/framework.Dvtg8yj2.js";const b=JSON.parse('{"title":"Lookahead 原文","description":"","frontmatter":{"title":"Lookahead 原文","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/fu-lookahead.md","filePath":"llm/fu-lookahead.md","lastUpdated":1788454257000}'),E={name:"llm/fu-lookahead.md"};function p(m,a,A,k,B,u){const i=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="lookahead-原文" tabindex="-1">Lookahead 原文 <a class="header-anchor" href="#lookahead-原文" aria-label="Permalink to &quot;Lookahead 原文&quot;">​</a></h1><div class="epigraph"><p>把自回归看成非线性方程组，用 Jacobi 迭代并行更新互不依赖的未来位置；猜错不可怕，只要把像样的 n-gram 存进池子，再用同一次前向精确验证。</p><footer>—— Fu, Bailis, Stoica, Zhang，Break the Sequential Dependency of LLM Inference Using Lookahead Decoding，2024</footer></div><p>草稿模型要训、要对齐、要进调度。<a href="/llm/specinfer">SpecInfer</a> 用小模型长树，<a href="/llm/medusa">Medusa</a> 用额外头，都还是「另有一套 \\(q\\)」。Fu、Bailis、Stoica、Zhang 的 Lookahead Decoding 问：目标模型 \\(f\\) 自己能不能既当提议器又当验证器？观察是 Jacobi 迭代可以同时刷新多个未来位置，尽管这些位置在当前因果链上并不合法；把轨迹切成 n-gram 缓存起来，等到当前后缀匹配再验证，就得到一种零额外参数的投机。本篇按原文写方程、二维窗口与验证枝；服务对照见 <a href="/llm/lookahead-decoding">Lookahead Decoding</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>记已提交前缀为 \\(x_{\\le t}\\)。自回归约束是</p> \\[x_{t+i}=f(x_{\\le t+i-1}),\\qquad i=1,2,\\ldots \\]<p>这是一组三角形依赖的非线性方程。逐步解码相当于 Gauss–Seidel：必须先解出 \\(x_{t+1}\\) 才能更新 \\(x_{t+2}\\)。GPU 的矩阵单元并不喜欢这种串行。Jacobi 迭代改成：用上一轮对未知数的全部猜测，并行写出本轮每个位置的新猜测。形式上</p> \\[x_{t+i}^{(j+1)}=f\\bigl(x_{\\le t},\\,x_{t+1}^{(j)},\\ldots,x_{t+i-1}^{(j)}\\bigr). \\]<p>朴素 Jacobi 解码几乎从不加速。早期位置错了，后面位置的「并行更新」全是在错误条件下算 \\(f\\)，接受长度接近 1，还多付了平行位置的 FLOPs 与 KV。原文要解决的不是「能不能并行猜」，而是「并行产生的碎片如何变成可复用、可精确验证的提议」，使得逐步依赖只在期望上被打断。</p><h3 id="为何坚持零辅助模型" tabindex="-1">为何坚持零辅助模型 <a class="header-anchor" href="#为何坚持零辅助模型" aria-label="Permalink to &quot;为何坚持零辅助模型&quot;">​</a></h3><p>小草稿难跟版本、难进多卡、在私有权重场景可能根本拿不到。Lookahead 把这一点写成与 Medusa 相同的痛点，给出的解却不是接头，而是把并行度花在 \\(f\\) 自己的一次更宽前向上。作者主张用逐步 \\(\\log(\\mathrm{FLOPs})\\) 量级的变贵，换解码步数的线性下降，并且能与 FlashAttention 一类 IO 感知核共存。对已经打满算力的大 batch decode，这条交换可能亏损；对单请求、代码补全、多卡把 lookahead 枝切开的设定，原文认为划算。</p><p><span class="marginnote">原文的「精确」指输出分布与原模型贪心或采样一致，不是指 Jacobi 猜测每次都对。猜测可以全错，验证枝拒绝它们，算法退化成略贵的一步自回归。加速全部来自池子里恰好接得上的 n-gram。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>算法维护一个二维窗口：横轴是未来位置，纵轴是 Jacobi 迭代轮次。宽度 \\(W\\) 是并行猜测的未来步数，\\(N\\) 是切下来的 n-gram 长度。每一轮对目标模型做一次带特制掩码的前向，同时走两枝。</p><h3 id="lookahead-枝-不相交-n-gram" tabindex="-1">Lookahead 枝：不相交 n-gram <a class="header-anchor" href="#lookahead-枝-不相交-n-gram" aria-label="Permalink to &quot;Lookahead 枝：不相交 n-gram&quot;">​</a></h3><p>Lookahead 枝按 Jacobi 规则更新窗口内 token：位置 \\(t+i\\) 看见的是上一轮窗口，而不是本轮刚刚写下的 \\(t+i-1\\)。因此同一轮里可以刷新若干段<strong>互不依赖</strong>的 n-gram。这些片段在当前已提交序列上并不构成合法续写，但作为「\\(f\\) 在相似局部上下文里可能再次说出的短语」是有信息的。它们被写入以起始 token 为键的 n-gram 池。池容量有限，用近期轨迹更新；没有外部语料，数据就是这次生成自己的 Jacobi 历史。</p><h3 id="验证枝-池中候选的一次核对" tabindex="-1">验证枝：池中候选的一次核对 <a class="header-anchor" href="#验证枝-池中候选的一次核对" aria-label="Permalink to &quot;验证枝：池中候选的一次核对&quot;">​</a></h3><p>验证枝用当前已提交后缀去池里取「以当前最后 token 开头」的候选 n-gram，用树状或分支掩码在同一次前向里核对。接受规则与投机采样同类：从左到右，目标分布同意则提交，直到第一处分歧。至少会提交一个真正的自回归 token（验证失败时的回退）。窗口随提交长度滑动，没用上的 n-gram 留在池里等后续后缀。</p>',18)),(e(),d(c,null,{default:t(()=>[s(i,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E4%BA%8C%E7%BB%B4%20Jacobi%20%E7%AA%97%E5%8F%A3%20W%20%C3%97%20%E8%BF%AD%E4%BB%A3%22%5D%20--%3E%20L%5B%22Lookahead%20%E6%9E%9D%E5%B9%B6%E8%A1%8C%E6%9B%B4%E6%96%B0%22%5D%0A%20%20L%20--%3E%20P%5B%22n-gram%20%E6%B1%A0%22%5D%0A%20%20S%5B%22%E5%B7%B2%E6%8F%90%E4%BA%A4%E5%90%8E%E7%BC%80%22%5D%20--%3E%20V%5B%22%E9%AA%8C%E8%AF%81%E6%9E%9D%E5%8C%B9%E9%85%8D%E5%80%99%E9%80%89%22%5D%0A%20%20P%20--%3E%20V%0A%20%20V%20--%3E%20A%7B%22%E7%B2%BE%E7%A1%AE%E9%AA%8C%E8%AF%81%E9%80%9A%E8%BF%87%3F%22%7D%0A%20%20A%20--%3E%7C%E6%98%AF%7C%20C%5B%22%E4%B8%80%E6%AC%A1%E6%8F%90%E4%BA%A4%E6%9C%80%E9%95%BF%E5%89%8D%E7%BC%80%22%5D%0A%20%20A%20--%3E%7C%E5%90%A6%7C%20O%5B%22%E5%9B%9E%E9%80%80%E4%B8%BA%201%20%E4%B8%AA%E8%87%AA%E5%9B%9E%E5%BD%92%20token%22%5D%0A%20%20C%20--%3E%20W%0A%20%20O%20--%3E%20W%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是「用看似浪费的并行 FLOPs 生产可复用短语，再用精确验证把短语接回因果链」。Jacobi 保证窗口更新没有逐步依赖；池保证短语的生命周期长于一次失败猜测；验证保证对外 token 流与逐步 \\(f\\) 不可区分。期望上，每当当前 token 是某个高质量 n-gram 的首词，一步可以前进约 \\(N\\) 个位置。\\(W\\) 与 \\(N\\) 增大，每步 FLOPs 与短暂 KV 上升，串行步数下降。原文把加速写成一条可调曲线，而不是固定倍数。</p><p>与参数化草稿相比，接受率完全由「\\(f\\) 是否反复说出同一 n-gram」决定，没有「草稿是否校准」这一项。低熵、高重复的域——代码补全、填表、带模板的客服——池命中高；高熵开放对话命中低。这是零草稿方法的信息论边界：没有另一个模型提供额外预测，并行只能挖掘 \\(f\\) 自己轨迹里的相关结构。</p><p><span class="marginnote">池不是检索增强。它不读文档库，只缓存本轮 Jacobi 片段。换会话应清空；连续批处理里必须按请求隔离，否则会把 A 的 n-gram 验证进 B 的上下文。对照检索式投机见 <a href="/llm/rest-spec">REST</a>。</span></p><h3 id="原文给出的数字该怎么读" tabindex="-1">原文给出的数字该怎么读 <a class="header-anchor" href="#原文给出的数字该怎么读" aria-label="Permalink to &quot;原文给出的数字该怎么读&quot;">​</a></h3><p>论文在 MT-bench 一类对话上报告相对自回归约 1.5–1.8× 量级；代码补全上更高，多 GPU 切 lookahead 枝时可达约 4×。这些数字随 \\(W\\)、\\(N\\)、模型宽度和采样温度变。温度升高，n-gram 可复用性下降，加速比通常不如贪心。引用时应写 Fu et al., arXiv:2402.02057，并区分对话与代码、单卡与多卡，不要把某一演示里的 7B 速度当成上限。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>Lookahead 不训练、不改权重，接入成本低，适合不能另服草稿的场景。它不降低 KV 随长度的增长，窗口额外位置还会短暂加大注意力。\\(W\\)、\\(N\\) 过大时单步变成 compute-bound，在已经很大的 decode batch 上可能负加速。验证必须真正计算目标 logits；若改成「池里有就直接用」，分布坏了，延迟也不可比。</p><p>不要把 Jacobi 解码本身叫做 Lookahead。没有池与验证枝，Jacobi 只是并行乱猜。也不要把后续的 EAGLE 特征外推或 MTP 训练目标说成 Jacobi 的别名：那些方法重新引入了可训练模块，换的是更高接受率，不再是原文的零参数约束。</p><p><span class="marginnote">加速比公式不能直接套 Leviathan 的草稿延迟比 \\(c\\)。应改成「每步窗口加候选的 token 数 / 每步实际提交 token 数」。接受率仍可定义，但统计的是池中 n-gram 被验证枝接受的比例，不是独立草稿 \\(\\alpha\\)。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>原文把自回归写成非线性方程，用 Jacobi 迭代在目标模型上并行产生不相交 n-gram。</li><li>二维窗口宽度 \\(W\\) 与 n-gram 长度 \\(N\\) 用逐步 FLOPs 换更少串行步；池缓存可复用短语。</li><li>验证枝保证与原解码分布一致；无验证则不是该算法。</li><li>加速依赖文本可复用性：代码高于开放对话；论文约 1.8×（MT-bench）与多卡代码约 4×。</li><li>池按请求隔离；过大窗口会打满算力墙。</li><li>出处：Fu et al., <em>Break the Sequential Dependency of LLM Inference Using Lookahead Decoding</em>，arXiv:2402.02057，2024。</li></ul>',12))])}const g=n(E,[["render",p]]);export{b as __pageData,g as default};
